test('Les lots de flux sont partagés entre deux instances du Worker',async()=>{const moduleA=await import('../worker/index.js?feed-test-a'),moduleB=await import('../worker/index.js?feed-test-b');const storage=memoryStore();let object;const env={SOCIAL_STORE:{idFromName:()=>1,get:()=>({fetch:r=>object.fetch(typeof r==='string'?new Request(r):r)})}};object=new moduleA.SocialStore({storage},env);const original=globalThis.fetch;let calls=0;globalThis.fetch=async url=>{calls++;if(String(url).includes('services.nvd.nist.gov'))return new Response(JSON.stringify({vulnerabilities:[]}));if(String(url).includes('known_exploited_vulnerabilities.json'))return new Response(JSON.stringify({vulnerabilities:[]}));return new Response(xml);};try{let last;for(const mod of Array.from({length:Math.ceil(SOURCES.filter(s=>s.enabled).length/FEED_BATCH_SIZE)},(_,i)=>i%2?moduleB:moduleA)){const before=calls;last=await(await mod.default.fetch(new Request('https://test/api/feed?continue=1'),env)).json();assert.ok(calls-before<=FEED_BATCH_SIZE);}assert.equal(last.pendingSources,0);assert.equal((await storage.list({prefix:'feed:'})).size,SOURCES.filter(s=>s.enabled).length);assert.equal(calls,SOURCES.filter(s=>s.enabled).length);}finally{globalThis.fetch=original;}});
test('Microsoft et SOC restent des étiquettes cumulables sans confondre SOC et SOC 2',async()=>{const {topicTags}=await import('../worker/index.js');const tags=topicTags('Microsoft Sentinel KQL detects Defender endpoint incidents after Windows patch deployment');for(const value of ['Microsoft','SOC','Gestion des correctifs'])assert.ok(tags.includes(value));const audit=topicTags('Audit du rapport SOC 2 et des exigences ISO 27001');assert.ok(audit.includes('Audit & conformité'));assert.ok(!audit.includes('SOC'));assert.ok(topicTags('Kubernetes supply chain SBOM').includes('DevSecOps'));});
test('Chaque référentiel demandé est présent une fois et les certifications historiques sont signalées',async()=>{const {AUDIT_REFERENCES,CERTIFICATION_DIRECTORY}=await import('../worker/index.js');assert.equal(AUDIT_REFERENCES.length,20);assert.equal(new Set(AUDIT_REFERENCES.map(r=>r.id)).size,20);for(const id of ['iso-19011','iso-27007','iso-27008','iso-27001','iso-27002','iso-27005','nist-800-53','cis-controls','cis-benchmarks','passi','secnumcloud','nis2','pci-dss','soc2','ptes','asvs','wstg','mastg','rgpd','osstmm'])assert.ok(AUDIT_REFERENCES.some(r=>r.id===id&&r.url&&r.exercise),id);assert.equal(CERTIFICATION_DIRECTORY.length,23);for(const code of ['OSCP','OSEP','OSWE','OSEE','CEH Practical','CPENT','eJPT','eCPPT','eWPTX','CRTP','CRTE','PNPT','GPEN','GWAPT','GXPN','CRT','CCT','SC-900','SC-200','SC-300','SC-100','AZ-500','MS-500'])assert.ok(CERTIFICATION_DIRECTORY.some(c=>c.code===code),code);assert.ok(CERTIFICATION_DIRECTORY.find(c=>c.code==='MS-500').status.includes('30/06/2023'));assert.ok(CERTIFICATION_DIRECTORY.find(c=>c.code==='AZ-500').status.includes('31/08/2026'));});
test('Les spécialisations Microsoft, SOC et audit disposent de laboratoires détaillés et de correspondances récentes',async()=>{const {LEARNING_TRACKS,learningMatches}=await import('../worker/index.js');for(const id of ['microsoft','soc','audit']){const track=LEARNING_TRACKS.find(t=>t.id===id);assert.equal(track.lessons.length,3);for(const lesson of track.lessons){assert.ok(lesson.technical.length>200);assert.ok(lesson.lab.action.length>100);assert.ok(lesson.lab.interpret.length>100);assert.ok(lesson.lab.solution.length>70);}}assert.equal(learningMatches('microsoft',{title:'Windows Intune security policy',summary:''}),true);assert.equal(learningMatches('soc',{title:'KQL Sentinel triage',summary:''}),true);assert.equal(learningMatches('audit',{title:'ISO 27001 audit des preuves',summary:''}),true);assert.equal(learningMatches('soc',{title:'Rapport SOC 2',summary:''}),false);assert.equal(SOURCES.filter(s=>s.id.startsWith('ms-')&&s.enabled).length,4);});
test('La copie Gemini contient le cours technique complet, le dialogue et la question',async()=>{const {buildCoursePrompt,LEARNING_TRACKS}=await import('../worker/index.js');const track=LEARNING_TRACKS.find(t=>t.id==='soc'),lesson=track.lessons[1];const text=buildCoursePrompt(track,lesson,'Pourquoi une fenêtre de cinq minutes ?','Complément déjà expliqué',[{role:'user',text:'Je débute en KQL'},{role:'assistant',text:'Commençons par une table.'}]);for(const expected of [track.name,lesson.goal,lesson.prerequisite,lesson.concept,lesson.technical,...Object.values(lesson.lab),lesson.question,lesson.answer,track.sources[0],'Complément déjà expliqué','Je débute en KQL','Pourquoi une fenêtre de cinq minutes ?'])assert.ok(text.includes(expected));assert.ok(text.endsWith('Pourquoi une fenêtre de cinq minutes ?'));assert.ok(!text.includes('APP_ACCESS_TOKEN'));});
