test('La connexion automatique et la relance LinkedIn précèdent le diagnostic, sans code ni activation manuelle',async()=>{const page=await(await worker.fetch(new Request('https://test/'),{},{})).text(),script=page.match(/<script[^>]*>([\s\S]*)<\/script>/)[1];const a=script.indexOf('function renderSources(){'),b=script.indexOf('\nasync function load()',a),elements=new Map();const context=vm.createContext({connectionStatus:{},accessToken:'fixture',followedPeople:[],sources:[],resources:[],lastSocialStatus:'',renderHealth(){},clearPrivateSession(){},esc:String,$:key=>{if(!elements.has(key))elements.set(key,{innerHTML:'',textContent:''});return elements.get(key);}});new vm.Script(script.slice(a,b)).runInContext(context);vm.runInContext('renderSources()',context);const html=elements.get('#sources-view').innerHTML;assert.ok(html.indexOf('Connexions privées')<html.indexOf('État des sources'));assert.ok(!html.includes('id="access-code"'));assert.ok(!html.includes('id="unlock"'));assert.ok(!html.includes('id="social-sync"'));assert.ok(html.includes('Connexion automatique via Cloudflare Access'));for(const id of ['lock','retry-linkedin']){assert.equal((html.match(new RegExp('id="'+id+'"','g'))||[]).length,1);assert.ok(html.indexOf('id="'+id+'"')<html.indexOf('État des sources'));}});
