async function accessFixture(){const pair=await crypto.subtle.generateKey({name:'RSASSA-PKCS1-v1_5',modulusLength:2048,publicExponent:new Uint8Array([1,0,1]),hash:'SHA-256'},true,['sign','verify']);const jwk={...await crypto.subtle.exportKey('jwk',pair.publicKey),kid:'test-access-key',alg:'RS256',use:'sig'};const {ACCESS_CONFIG}=await import('../worker/index.js');const encode=v=>Buffer.from(JSON.stringify(v)).toString('base64url');return {jwk,async sign(extra={},header={}){const now=Math.floor(Date.now()/1000);const input=encode({alg:'RS256',kid:jwk.kid,...header})+'.'+encode({iss:ACCESS_CONFIG.issuer,aud:[ACCESS_CONFIG.audience],type:'app',email:'owner@example.com',iat:now-10,exp:now+3600,...extra});const signature=await crypto.subtle.sign('RSASSA-PKCS1-v1_5',pair.privateKey,new TextEncoder().encode(input));return input+'.'+Buffer.from(signature).toString('base64url');}};}
test('Cloudflare Access ouvre automatiquement les fonctions privées après vérification cryptographique, sans code personnel',async()=>{const fixture=await accessFixture();const mod=await import('../worker/index.js?access-verified-test');const token=await fixture.sign();const original=globalThis.fetch;let keyReads=0;globalThis.fetch=async url=>{assert.equal(url,mod.ACCESS_CONFIG.issuer+'/cdn-cgi/access/certs');keyReads++;return new Response(JSON.stringify({keys:[fixture.jwk]}));};try{const headers={'Cf-Access-Jwt-Assertion':token,Origin:'https://test'};assert.equal(await mod.authorized(new Request('https://test/api/social',{headers}),{}),true);const r=await mod.default.fetch(new Request('https://test/api/session',{method:'POST',headers}),{},{});assert.equal(r.status,200);assert.deepEqual(await r.json(),{ok:true,token:'cloudflare-access',access:true});const status=await(await mod.default.fetch(new Request('https://test/api/status',{headers}),{},{})).json();assert.equal(status.access,true);assert.equal(status.protected,true);assert.equal(keyReads,1);const wrongOrigin=await mod.default.fetch(new Request('https://test/api/session',{method:'POST',headers:{...headers,Origin:'https://other.example'}}),{},{});assert.equal(wrongOrigin.status,403);}finally{globalThis.fetch=original;}});
test('La connexion automatique refuse les jetons falsifiés, expirés, d’une autre application et les simples en-têtes',async()=>{const fixture=await accessFixture();const mod=await import('../worker/index.js?access-invalid-test');const original=globalThis.fetch;globalThis.fetch=async()=>new Response(JSON.stringify({keys:[fixture.jwk]}));try{const valid=await fixture.sign();const badSignature=valid.slice(0,valid.lastIndexOf('.')+1)+Buffer.alloc(256).toString('base64url');const tokens=[badSignature,await fixture.sign({aud:['another-app']}),await fixture.sign({iss:'https://attacker.cloudflareaccess.com'}),await fixture.sign({exp:Math.floor(Date.now()/1000)-1}),await fixture.sign({nbf:Math.floor(Date.now()/1000)+600}),await fixture.sign({type:'service'}),await fixture.sign({}, {alg:'none'}),'not.a.jwt'];for(const token of tokens)assert.equal(await mod.authorized(new Request('https://test/api/social',{headers:{'Cf-Access-Jwt-Assertion':token}}),{}),false);const r=await mod.default.fetch(new Request('https://test/api/social',{headers:{Authorization:'Bearer cloudflare-access','Cf-Access-Authenticated-User-Email':'owner@example.com'}}),{},{});assert.equal(r.status,401);}finally{globalThis.fetch=original;}});
test('La collecte automatique respecte les échéances et ne double pas les lancements ni les réservations',async()=>{const mod=await import('../worker/index.js?auto-social-schedule-test');const storage=memoryStore();let object,starts=0;const env={APP_ACCESS_TOKEN:'automatic-social-test-token-long',BRIGHTDATA_TOKEN:'fixture',BRIGHTDATA_FREE_ONLY_CONFIRMED:'true',SOCIAL_STORE:{idFromName:()=>1,get:()=>({fetch:r=>object.fetch(typeof r==='string'?new Request(r):r)})}};object=new mod.SocialStore({storage},env);const original=globalThis.fetch;globalThis.fetch=async(url,options={})=>{if(options.method==='POST'){starts++;return new Response(JSON.stringify({snapshot_id:'auto_'+starts}));}return new Response(JSON.stringify({status:'running'}));};try{const req=()=>new Request('https://test/api/social/auto',{method:'POST',headers:{Origin:'https://test',Authorization:'Bearer '+env.APP_ACCESS_TOKEN}});assert.equal((await mod.default.fetch(req(),env,{})).status,200);assert.equal(starts,2);assert.equal((await storage.get('state')).budget.used,40);assert.equal((await mod.default.fetch(req(),env,{})).status,200);assert.equal(starts,2);assert.equal((await storage.get('state')).budget.used,40);const blocked=await mod.default.fetch(req(),{...env,BRIGHTDATA_FREE_ONLY_CONFIRMED:'false'},{});assert.equal(blocked.status,200);assert.equal(starts,2);}finally{globalThis.fetch=original;}});

