test('Les traductions ne consomment pas de quota pendant une formation ou en mode à la demande',async()=>{const h=await translationHarness([{id:'waiting',language:'en',title:'Security update',summary:'Apply the update'}],async()=>{throw Error('No API work expected');});h.context.view='tutorials';await h.run();assert.equal(h.requests.length,0);assert.match(h.elements.get('#translation-status').textContent,/pause/);h.context.view='feed';vm.runInContext("aiWorkload='manual'",h.context);await h.run();assert.equal(h.requests.length,0);assert.match(h.elements.get('#translation-status').textContent,/demande/);});
test('Une question prioritaire attend la traduction déjà envoyée puis est transmise une seule fois',async()=>{const page=await(await worker.fetch(new Request('https://test/'),{},{})).text(),js=page.match(/<script[^>]*>([\s\S]*)<\/script>/)[1];const code=js.slice(js.indexOf("let aiWorkload='balanced'"),js.indexOf('function looksFrench('));const calls=[],messages=[];let restarts=0;const ctx=vm.createContext({privateEpoch:0,translationRunning:true,translationTimer:null,localStorage:{getItem:()=>null},setTimeout,clearTimeout,DOMException,fetch:async url=>{calls.push(url);return {ok:true};},startAutoTranslation(){restarts++;}});new vm.Script(code).runInContext(ctx);ctx.progress=s=>messages.push(s);const task=vm.runInContext("interactiveFetch('/api/course-chat',{},progress)",ctx);await new Promise(resolve=>setTimeout(resolve,5));assert.equal(calls.length,0);ctx.translationRunning=false;assert.equal((await task).ok,true);assert.deepEqual(calls,['/api/course-chat']);assert.ok(messages.some(s=>s.includes('prioritaire')));assert.equal(restarts,1);});
test('Le cache de tutorat réutilise uniquement la même question et le même contexte sans rappel Gemini',async()=>{const mod=await import('../worker/index.js?edr-tutor-cache');const env={APP_ACCESS_TOKEN:'edr-tutor-cache-owner-token-long',GEMINI_API_KEY:'fixture',GEMINI_FREE_TIER_CONFIRMED:'true'};const original=globalThis.fetch;let calls=0;globalThis.fetch=async url=>{assert.ok(String(url).startsWith('https://generativelanguage.googleapis.com/'));calls++;return new Response(JSON.stringify({candidates:[{content:{parts:[{text:'Defender Antivirus protège localement ; le rattachement EDR doit être vérifié séparément.'}]},finishReason:'STOP'}]}));};const request=(question,history=[])=>new Request('https://test/api/course-chat',{method:'POST',headers:{Origin:'https://test',Authorization:'Bearer '+env.APP_ACCESS_TOKEN},body:JSON.stringify({id:'defender-1',question,history})});try{assert.equal((await mod.default.fetch(request('AV et EDR ?'),env,{})).status,200);const cached=await(await mod.default.fetch(request('AV et EDR ?'),env,{})).json();assert.equal(cached.cached,true);assert.equal(calls,1);const changed=await mod.default.fetch(request('Une autre question'),env,{});assert.equal(changed.status,429);assert.equal((await changed.json()).cached,undefined);const dialogue=await mod.default.fetch(request('AV et EDR ?',[{role:'user',text:'Nouveau contexte'}]),env,{});assert.equal(dialogue.status,429);assert.equal(calls,1);}finally{globalThis.fetch=original;}});

test('Les options de réflexion rapide sont limitées aux modèles Flash qui les prennent en charge',async()=>{const mod=await import('../worker/index.js?model-aware-thinking');const original=globalThis.fetch,seen=[];globalThis.fetch=async(url,options)=>{seen.push(JSON.parse(options.body).generationConfig);return new Response(JSON.stringify({candidates:[{content:{parts:[{text:'Réponse de test'}]},finishReason:'STOP'}]}));};try{for(const model of ['gemini-2.5-flash','gemini-2.5-pro']){const env={GEMINI_API_KEY:'fixture',GEMINI_MODEL:model,APP_ACCESS_TOKEN:'model-options-fixture-token-long'};await mod.generateExplanation('gemini',env,[]);}assert.deepEqual(seen[0].thinkingConfig,{thinkingBudget:0});assert.equal(seen[1].thinkingConfig,undefined);}finally{globalThis.fetch=original;}});
